SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name='deleted_at')=0,'ALTER TABLE users ADD COLUMN deleted_at DATETIME NULL AFTER is_active','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name='deleted_by')=0,'ALTER TABLE users ADD COLUMN deleted_by INT NULL AFTER deleted_at','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name='deletion_reason')=0,'ALTER TABLE users ADD COLUMN deletion_reason VARCHAR(500) NULL AFTER deleted_by','SELECT 1'); PREPARE s FROM @q; EXECUTE s; DEALLOCATE PREPARE s;
CREATE TABLE IF NOT EXISTS admin_audits (id INT AUTO_INCREMENT PRIMARY KEY,actor_id INT NULL,action VARCHAR(100) NOT NULL,target_type VARCHAR(50) NOT NULL,target_id INT NULL,details TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_admin_audits_actor_created(actor_id,created_at),CONSTRAINT fk_admin_audits_actor FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
